// WlShmEvents holds the callbacks for the events of wl_shm. A nil callback ignores the event.
type WlShmEvents struct {
	// OnFormat: pixel format description
	OnFormat func(format WlShmFormat)
}

// SetEvents sets the callbacks for the events of the object. It replaces the previous ones.
func (self *WlShm) SetEvents(events *WlShmEvents) { self.events = events }

func (self *WlShm) dispatch(opcode uint32, a eventArgs) {
	ev := self.events
	switch opcode {
	case 0: // format
		if ev == nil || ev.OnFormat == nil {
			return
		}
		ev.OnFormat(WlShmFormat(a.uint(0)))
	}
}

// CreatePool: create a shm pool.
func (self *WlShm) CreatePool(fd int, size int32) *WlShmPool {
	argv := newArgs(3)
	defer argv.free()
	argv.setFD(1, int32(fd))
	argv.setInt(2, size)
	proxy := self.marshal(0, WlShmPoolInterface, self.version, 0, argv)
	if proxy == 0 {
		return nil
	}
	return newWlShmPool(self.conn, proxy)
}

// Release: release the shm object. It destroys the object. Since version 2.
func (self *WlShm) Release() {
	argv := newArgs(0)
	defer argv.free()
	self.marshal(1, nil, self.version, flagDestroy, argv)
}

// WlBuffer: content for a wl_surface
type WlBuffer struct {
	Proxy
	events *WlBufferEvents
}

// WlBufferInterface describes wl_buffer, up to version 1.
var WlBufferInterface = newInterface("wl_buffer", 1)

func init() {
	WlBufferInterface.setMessages(
		[]message{
			{"destroy", "", []*Interface{}},
		},
		[]message{
			{"release", "", []*Interface{}},
		},
	)
}

func newWlBuffer(c *Conn, proxy uintptr) *WlBuffer {
	self := new(WlBuffer)
	c.register(self, proxy, true)
	return self
}

// Ptr returns the wl_proxy pointer, or 0 for a nil WlBuffer.
func (self *WlBuffer) Ptr() uintptr {
	if self == nil {
		return 0
	}
	return self.ptr
}

// BindWlBuffer binds the global wl_buffer with the given registry name and version.
func BindWlBuffer(registry *WlRegistry, name, version uint32) *WlBuffer {
	proxy := registry.BindRaw(name, WlBufferInterface, version)
	if proxy == 0 {
		return nil
	}
	return newWlBuffer(registry.conn, proxy)
}

// WlBufferEvents holds the callbacks for the events of wl_buffer. A nil callback ignores the event.
type WlBufferEvents struct {
	// OnRelease: compositor releases buffer
	OnRelease func()
}

// SetEvents sets the callbacks for the events of the object. It replaces the previous ones.
func (self *WlBuffer) SetEvents(events *WlBufferEvents) { self.events = events }

func (self *WlBuffer) dispatch(opcode uint32, a eventArgs) {
	ev := self.events
	switch opcode {
	case 0: // release
		if ev == nil || ev.OnRelease == nil {
			return
		}
		ev.OnRelease()
	}
}

// Destroy: destroy a buffer. It destroys the object.
func (self *WlBuffer) Destroy() {
	argv := newArgs(0)
	defer argv.free()
	self.marshal(0, nil, self.version, flagDestroy, argv)
}

// WlDataOffer: offer to transfer data
type WlDataOffer struct {
	Proxy
	events *WlDataOfferEvents
}

// WlDataOfferInterface describes wl_data_offer, up to version 4.
var WlDataOfferInterface = newInterface("wl_data_offer", 4)

func init() {
	WlDataOfferInterface.setMessages(
		[]message{
			{"accept", "u?s", []*Interface{nil, nil}},
			{"receive", "sh", []*Interface{nil, nil}},
			{"destroy", "", []*Interface{}},
			{"finish", "3", []*Interface{}},
			{"set_actions", "3uu", []*Interface{nil, nil}},
		},
		[]message{
			{"offer", "s", []*Interface{nil}},
			{"source_actions", "3u", []*Interface{nil}},
			{"action", "3u", []*Interface{nil}},
		},
	)
}

func newWlDataOffer(c *Conn, proxy uintptr) *WlDataOffer {
	self := new(WlDataOffer)
	c.register(self, proxy, true)
	return self
}

// Ptr returns the wl_proxy pointer, or 0 for a nil WlDataOffer.
func (self *WlDataOffer) Ptr() uintptr {
	if self == nil {
		return 0
	}
	return self.ptr
}

// BindWlDataOffer binds the global wl_data_offer with the given registry name and version.
func BindWlDataOffer(registry *WlRegistry, name, version uint32) *WlDataOffer {
	proxy := registry.BindRaw(name, WlDataOfferInterface, version)
	if proxy == 0 {
		return nil
	}
	return newWlDataOffer(registry.conn, proxy)
}

// WlDataOfferError:
type WlDataOfferError uint32

const (
	// WlDataOfferErrorInvalidFinish: finish request was called untimely
	WlDataOfferErrorInvalidFinish WlDataOfferError = 0
	// WlDataOfferErrorInvalidActionMask: action mask contains invalid values
	WlDataOfferErrorInvalidActionMask WlDataOfferError = 1
	// WlDataOfferErrorInvalidAction: action argument has an invalid value
	WlDataOfferErrorInvalidAction WlDataOfferError = 2
	// WlDataOfferErrorInvalidOffer: offer doesn't accept this request
	WlDataOfferErrorInvalidOffer WlDataOfferError = 3
)

// WlDataOfferEvents holds the callbacks for the events of wl_data_offer. A nil callback ignores the event.
type WlDataOfferEvents struct {
	// OnOffer: advertise offered mime type
	OnOffer func(mimeType string)
	// OnSourceActions: notify the source-side available actions
	OnSourceActions func(sourceActions WlDataDeviceManagerDndAction)
	// OnAction: notify the selected action
	OnAction func(dndAction WlDataDeviceManagerDndAction)
}

// SetEvents sets the callbacks for the events of the object. It replaces the previous ones.
func (self *WlDataOffer) SetEvents(events *WlDataOfferEvents) { self.events = events }

func (self *WlDataOffer) dispatch(opcode uint32, a eventArgs) {
	ev := self.events
	switch opcode {
	case 0: // offer
		if ev == nil || ev.OnOffer == nil {
			return
		}
		ev.OnOffer(a.str(0))
	case 1: // source_actions
		if ev == nil || ev.OnSourceActions == nil {
			return
		}
		ev.OnSourceActions(WlDataDeviceManagerDndAction(a.uint(0)))
	case 2: // action
		if ev == nil || ev.OnAction == nil {
			return
		}
		ev.OnAction(WlDataDeviceManagerDndAction(a.uint(0)))
	}
}

// Accept: accept one of the offered mime types.
func (self *WlDataOffer) Accept(serial uint32, mimeType string) {
	argv := newArgs(2)
	defer argv.free()
	argv.setUint(0, serial)
	argv.setNullableString(1, mimeType)
	self.marshal(0, nil, self.version, 0, argv)
}

// Receive: request that the data is transferred.
func (self *WlDataOffer) Receive(mimeType string, fd int) {
	argv := newArgs(2)
	defer argv.free()
	argv.setString(0, mimeType)
	argv.setFD(1, int32(fd))
	self.marshal(1, nil, self.version, 0, argv)
}

// Destroy: destroy data offer. It destroys the object.
func (self *WlDataOffer) Destroy() {
	argv := newArgs(0)
	defer argv.free()
	self.marshal(2, nil, self.version, flagDestroy, argv)
}

// Finish: the offer will no longer be used. Since version 3.
func (self *WlDataOffer) Finish() {
	argv := newArgs(0)
	defer argv.free()
	self.marshal(3, nil, self.version, 0, argv)
}

// SetActions: set the available/preferred drag-and-drop actions. Since version 3.
func (self *WlDataOffer) SetActions(dndActions WlDataDeviceManagerDndAction, preferredAction WlDataDeviceManagerDndAction) {
	argv := newArgs(2)
	defer argv.free()
	argv.setUint(0, uint32(dndActions))
	argv.setUint(1, uint32(preferredAction))
	self.marshal(4, nil, self.version, 0, argv)
}

